SELECT *
FROM (

) grouped_history
WHERE knownMembershipCount = 0 OR adminInGroup = 1
ORDER BY groupJid ASC
LIMIT #{offset}, #{pageSize}

SELECT phone.groupJid, phone.accountPhone, MAX(phone.currentRelation) AS currentRelation FROM ( SELECT baseline_phone.group_jid AS groupJid, a.id AS accountId, a.ws_phone AS accountPhone, 0 AS currentRelation FROM account a INNER JOIN account_group_baseline b ON b.tenant_id = a.tenant_id AND b.account_id = a.id INNER JOIN JSON_TABLE( b.baseline_group_jids, '$[*]' COLUMNS (group_jid VARCHAR(128) PATH '$') ) baseline_phone WHERE a.tenant_id = #{tenantId} AND a.account_group_id = #{accountGroupId} AND a.deleted_at IS NULL AND a.ws_phone IS NOT NULL AND TRIM(a.ws_phone) <> '' AND baseline_phone.group_jid IN
#{groupJid}
UNION ALL SELECT current_phone.group_jid AS groupJid, a.id AS accountId, a.ws_phone AS accountPhone, 1 AS currentRelation FROM account_group_membership current_phone INNER JOIN account a ON a.tenant_id = current_phone.tenant_id AND a.id = current_phone.account_id WHERE a.tenant_id = #{tenantId} AND a.account_group_id = #{accountGroupId} AND a.deleted_at IS NULL AND a.ws_phone IS NOT NULL AND TRIM(a.ws_phone) <> '' AND current_phone.deleted_at IS NULL AND current_phone.membership_status = #{inGroupStatus} AND current_phone.group_jid IN
#{groupJid}
) phone GROUP BY phone.groupJid, phone.accountPhone ORDER BY phone.groupJid ASC, MAX(phone.currentRelation) DESC, MIN(phone.accountId) ASC

