UPDATE account
SET group_baseline_state = 2,
    updated_at = #{now}
WHERE id = #{accountId}
  AND deleted_at IS NULL
  AND group_baseline_state = 1

mapper.select:
SELECT group_link_id FROM group_link_preview WHERE group_link_id IN
#{groupLinkId}
ORDER BY group_link_id ASC

SELECT group_jid FROM account_group_membership WHERE account_id = #{accountId} AND deleted_at IS NULL AND group_jid IN
#{groupJid}
ORDER BY group_jid ASC

SELECT a.id AS accountId, a.protocol_id AS protocolId, a.protocol_account_id AS protocolAccountId, a.ws_phone AS wsPhone, TRUE AS groupAdmin FROM group_link g INNER JOIN account a ON a.tenant_id = g.tenant_id AND a.deleted_at IS NULL AND a.protocol_account_id IS NOT NULL AND a.protocol_account_id != '' AND a.ws_phone IS NOT NULL AND a.ws_phone != '' INNER JOIN account_state s ON s.tenant_id = a.tenant_id AND s.account_id = a.id AND s.login_state = #{onlineLoginState} AND s.account_state = #{normalAccountState} LEFT JOIN account_group_membership m ON m.tenant_id = g.tenant_id AND m.group_link_id = g.id AND m.account_id = a.id AND m.deleted_at IS NULL AND m.membership_status = 1 WHERE g.id = #{groupLinkId} AND g.deleted_at IS NULL AND a.ws_phone IN
#{phone}
ORDER BY COALESCE(m.last_seen_at, 0) DESC, a.id ASC LIMIT #{limit}

SELECT id
FROM account_group_membership
WHERE account_id = #{accountId}
  AND deleted_at IS NULL
  AND membership_status NOT IN

    #{preservedStatus}

  AND (
    status_updated_at < #{statusUpdatedAt}
    OR (
      status_updated_at = #{statusUpdatedAt}
      AND status_source NOT IN ('WGP2_ADD', 'WGP2_REMOVE', 'WGP2_LEAVE')
    )
  )

  AND group_jid NOT IN
  #{jid}

ORDER BY id ASC

